// Priority Constants (which argument)
#define PRIO_PROCESS 0
#define PRIO_PGRP    1
#define PRIO_USER    2

// Retrieve priority (nice value: typically -20 to 19)
int nice_value;
id_t target_id = getpid(); // Example target ID

// 1. Query current process
nice_value = getpriority(PRIO_PROCESS, 0);

// 2. Query specific process ID
nice_value = getpriority(PRIO_PROCESS, target_id);

// 3. Query specific user ID
id_t target_uid = getuid();
nice_value = getpriority(PRIO_USER, target_uid);

// Return Value: Nice value, or -1 on failure.
// Must check errno if result is -1, as -1 is a valid nice value.
if (nice_value == -1 && errno != 0) {
    // Handle error (e.g., ESRCH, EPERM)
}
